/* 脉络 · 依赖关系网 —— 深色主题样式 */
:root {
  color-scheme: dark;
  --bg: #0a101e;
  --surface: #101a2e;
  --surface-2: #16233c;
  --canvas: #0d1526;
  --ink-1: #eef3fb;
  --ink-2: #a8b6cc;
  --ink-3: #6b7a94;
  --hairline: rgba(255, 255, 255, 0.09);
  --hairline-2: rgba(255, 255, 255, 0.05);

  /* 关系类型色（三类，全部配线型冗余编码；已按深色底验证） */
  --c-call: #3987e5;
  --c-event: #d95926;
  --c-data: #199e70;
  /* 跟随路径 */
  --c-trace: #e8f1ff;

  /* 关键性（状态色，永远带文字标签出现） */
  --crit-p0-bg: rgba(208, 59, 59, 0.20);
  --crit-p0-tx: #ff9b9b;
  --crit-p1-bg: rgba(250, 178, 25, 0.14);
  --crit-p1-tx: #f5c964;
  --crit-p2-bg: rgba(255, 255, 255, 0.07);
  --crit-p2-tx: #9aa8bf;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--ink-1);
  font: 14px/1.55 system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
button:focus-visible, input:focus-visible { outline: 2px solid #6da7ec; outline-offset: 1px; }

/* ── 顶栏 ─────────────────────────────────────────────── */
#topbar {
  height: 56px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--hairline);
}
.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.logo {
  width: 32px; height: 32px; border-radius: 8px;
  background: linear-gradient(135deg, #1c5cab, #3987e5);
  display: grid; place-items: center;
  font-weight: 700; font-size: 16px; color: #fff;
}
.brand h1 { font-size: 15px; font-weight: 650; letter-spacing: 0.02em; white-space: nowrap; }
.brand h1 span { color: var(--ink-2); font-weight: 450; }
.brand p { font-size: 11px; color: var(--ink-3); white-space: nowrap; }

.search-wrap { position: relative; margin-left: auto; }
#search {
  width: 240px; height: 32px;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 8px;
  color: var(--ink-1);
  padding: 0 10px 0 30px;
  font-size: 13px;
}
#search::placeholder { color: var(--ink-3); }
.search-wrap::before {
  content: "⌕"; position: absolute; left: 10px; top: 5px;
  color: var(--ink-3); font-size: 15px; pointer-events: none;
}
.search-drop {
  position: absolute; top: 36px; left: 0; right: 0; z-index: 40;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  overflow: hidden;
}
.search-drop button {
  display: flex; width: 100%; align-items: center; gap: 8px;
  padding: 7px 10px; font-size: 13px; text-align: left;
}
.search-drop button:hover, .search-drop button.hot { background: rgba(57, 135, 229, 0.18); }
.search-drop .s-lane { margin-left: auto; font-size: 11px; color: var(--ink-3); }

.topstats { font-size: 12px; color: var(--ink-2); white-space: nowrap; }
.topstats b { color: var(--ink-1); font-variant-numeric: tabular-nums; }
.btn {
  height: 32px; padding: 0 12px;
  border: 1px solid var(--hairline);
  border-radius: 8px;
  font-size: 12.5px; color: var(--ink-2);
  background: var(--surface-2);
  transition: color 0.15s, border-color 0.15s;
}
.btn:hover { color: var(--ink-1); border-color: rgba(255, 255, 255, 0.22); }

/* ── 主区布局 ─────────────────────────────────────────── */
main { flex: 1; display: flex; min-height: 0; }
#stage { flex: 1; position: relative; min-width: 0; background: var(--canvas); }
#graph { width: 100%; height: 100%; display: block; cursor: grab; }
#graph.panning { cursor: grabbing; }

/* ── SVG 图元 ─────────────────────────────────────────── */
.lane-sep { stroke: var(--hairline-2); stroke-dasharray: 2 5; }
.lane-name { fill: var(--ink-3); font-size: 12px; letter-spacing: 0.14em; }
.lane-count { fill: var(--ink-3); font-size: 11px; }

.edge-line { fill: none; transition: opacity 0.18s, stroke-width 0.12s; }
.edge-hit { fill: none; stroke: transparent; stroke-width: 14; cursor: pointer; }
.e-call  { stroke: var(--c-call);  stroke-width: 1.6; }
.e-event { stroke: var(--c-event); stroke-width: 1.6; stroke-dasharray: 6 4; }
.e-data  { stroke: var(--c-data);  stroke-width: 1.3; }
.edge-g { transition: opacity 0.18s; }
.edge-g:hover .edge-line, .edge-g.peek .edge-line, .edge-g.hl .edge-line { stroke-width: 3; }

.node-g { cursor: pointer; transition: opacity 0.18s; }
.node-box {
  fill: var(--surface-2);
  stroke: var(--hairline);
  stroke-width: 1;
  rx: 9;
  transition: stroke 0.12s;
}
.node-accent { rx: 0; }
.node-g:hover .node-box { stroke: rgba(255, 255, 255, 0.35); }
.node-g.ext .node-box { stroke-dasharray: 4 3; }
.node-name { fill: var(--ink-1); font-size: 13px; }
.node-g.dim, .edge-g.dim { opacity: 0.13; }

/* 聚焦态 */
.node-g.focus .node-box { stroke: var(--c-trace); stroke-width: 2; }
.focus-ring {
  fill: none; stroke: var(--c-trace); stroke-width: 1;
  opacity: 0.55; rx: 13;
  animation: breathe 1.8s ease-in-out infinite;
}
@keyframes breathe { 50% { opacity: 0.15; } }

/* 跟随路径：加亮描边流动 */
.edge-g.trace .edge-line {
  stroke: var(--c-trace) !important;
  stroke-width: 2.6;
  stroke-dasharray: 9 5;
  animation: flow 0.9s linear infinite;
}
@keyframes flow { to { stroke-dashoffset: -14; } }
.edge-g.trace .edge-line.e-event { stroke-dasharray: 9 5; }
.edge-g.trace marker { fill: var(--c-trace); }

/* 全局上下文：聚焦时其余图元只降暗，永不隐藏 */
svg.has-focus .edge-g:not(.hl):not(.trace), svg.has-focus .node-g:not(.hl):not(.focus) { opacity: 0.13; }

/* ── 浮层控件 ─────────────────────────────────────────── */
.modes {
  position: absolute; top: 12px; right: 12px;
  display: flex;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 9px;
  overflow: hidden;
}
.modes button { padding: 6px 12px; font-size: 12px; color: var(--ink-2); }
.modes button + button { border-left: 1px solid var(--hairline); }
.modes button.on { background: rgba(57, 135, 229, 0.25); color: var(--ink-1); font-weight: 600; }

.viewctl {
  position: absolute; right: 12px; bottom: 12px;
  display: flex; flex-direction: column; gap: 6px;
}
.viewctl button {
  width: 30px; height: 30px;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 8px;
  font-size: 15px; color: var(--ink-2); line-height: 1;
}
.viewctl button:hover { color: var(--ink-1); }

.legend {
  position: absolute; left: 12px; bottom: 12px;
  background: rgba(16, 26, 46, 0.88);
  border: 1px solid var(--hairline);
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 12px; color: var(--ink-2);
  backdrop-filter: blur(4px);
}
.lg-title { font-size: 11px; color: var(--ink-3); letter-spacing: 0.12em; margin-bottom: 6px; }
.lg-row { display: flex; align-items: center; gap: 8px; margin: 4px 0; }
.lg-line { width: 26px; height: 0; border-top: 2.5px solid var(--c, var(--ink-2)); }
.lg-line.dashed { border-top-style: dashed; }
.lg-line.thin { border-top-width: 1.5px; }
.lg-chips { margin-top: 6px; }
.lg-hint { margin-top: 7px; padding-top: 7px; border-top: 1px solid var(--hairline-2); color: var(--ink-3); font-size: 11px; }

/* 跟随面包屑 */
.tracebar {
  position: absolute; top: 12px; left: 50%;
  transform: translateX(-50%);
  max-width: calc(100% - 200px);
  display: flex; align-items: center; flex-wrap: wrap; gap: 4px;
  background: rgba(16, 26, 46, 0.92);
  border: 1px solid var(--hairline);
  border-radius: 11px;
  padding: 6px 10px;
  backdrop-filter: blur(4px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}
.crumb {
  padding: 3px 9px;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 7px;
  font-size: 12.5px; color: var(--ink-1);
}
.crumb:hover { border-color: rgba(255, 255, 255, 0.3); }
.crumb.cur { border-color: var(--c-trace); box-shadow: 0 0 0 1px var(--c-trace) inset; }
.crumb-sep { color: var(--ink-3); font-size: 12px; padding: 0 2px; user-select: none; }
.crumb-meta { font-size: 11.5px; color: var(--ink-3); margin-left: 6px; white-space: nowrap; }
.tracebar .btn { height: 24px; padding: 0 8px; margin-left: 6px; font-size: 11.5px; }

/* 提示气泡 */
.tooltip {
  position: absolute; z-index: 50;
  pointer-events: none;
  background: #1b2947;
  border: 1px solid var(--hairline);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 12px; color: var(--ink-1);
  max-width: 300px;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
}
.tooltip .tt-sub { color: var(--ink-2); font-size: 11.5px; }

/* ── 右侧上下文面板 ───────────────────────────────────── */
#panel {
  flex: 0 0 340px;
  background: var(--surface);
  border-left: 1px solid var(--hairline);
  overflow-y: auto;
  padding: 16px;
}
.pkick { font-size: 11px; letter-spacing: 0.14em; color: var(--ink-3); margin-bottom: 6px; }
#panel h2 { font-size: 19px; font-weight: 650; margin-bottom: 4px; }
#panel h3 {
  font-size: 12px; font-weight: 600; color: var(--ink-2);
  margin: 18px 0 8px;
  padding-top: 12px;
  border-top: 1px solid var(--hairline-2);
}
#panel h3 small { color: var(--ink-3); font-weight: 400; margin-left: 6px; }
.pdesc { font-size: 12.5px; color: var(--ink-2); }
.pnote { font-size: 12.5px; color: var(--ink-2); margin-top: 8px; }
.pcard-sec { margin-bottom: 4px; }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.chip {
  font-size: 11.5px; color: var(--ink-2);
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 6px;
  padding: 2px 8px;
}
.chip .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 5px; vertical-align: 0; }

.statrow {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 6px; margin-top: 14px;
}
.statrow > div {
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 9px;
  padding: 8px 4px;
  text-align: center;
}
.statrow b { display: block; font-size: 17px; font-weight: 650; font-variant-numeric: tabular-nums; }
.statrow span { font-size: 10.5px; color: var(--ink-3); }

.statrow.grid3 { grid-template-columns: repeat(3, 1fr); }

.rel-list { display: flex; flex-direction: column; gap: 5px; }
.rel {
  display: flex; align-items: center; gap: 7px;
  width: 100%; text-align: left;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 8px;
  padding: 6px 9px;
  transition: border-color 0.12s;
}
.rel:hover { border-color: rgba(255, 255, 255, 0.3); }
.rel-name { font-size: 13px; color: var(--ink-1); white-space: nowrap; }
.rel-label { font-size: 11px; color: var(--ink-3); margin-left: auto; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 46%; }
.tbadge { font-size: 10.5px; border-radius: 5px; padding: 1px 6px; flex: 0 0 auto; }
.tbadge.call  { background: rgba(57, 135, 229, 0.16);  color: #8db9f0; }
.tbadge.event { background: rgba(217, 89, 38, 0.18);   color: #f0a184; }
.tbadge.data  { background: rgba(25, 158, 112, 0.16);  color: #6fd0a8; }
.crit { font-size: 10px; border-radius: 5px; padding: 1px 5px; flex: 0 0 auto; font-variant-numeric: tabular-nums; }
.crit.p0 { background: var(--crit-p0-bg); color: var(--crit-p0-tx); }
.crit.p1 { background: var(--crit-p1-bg); color: var(--crit-p1-tx); }
.crit.p2 { background: var(--crit-p2-bg); color: var(--crit-p2-tx); }

.edgerel { display: flex; align-items: center; gap: 8px; margin: 10px 0 2px; flex-wrap: wrap; }
.edgerel button {
  padding: 5px 10px;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  border-radius: 8px; font-size: 13px;
}
.edgerel button:hover { border-color: rgba(255, 255, 255, 0.3); }
.edge-arrow { font-size: 13px; letter-spacing: -1px; }
.edge-arrow.call  { color: var(--c-call); }
.edge-arrow.event { color: var(--c-event); }
.edge-arrow.data  { color: var(--c-data); }

.btnrow { display: flex; gap: 8px; margin-top: 14px; flex-wrap: wrap; }
.empty-list { font-size: 12px; color: var(--ink-3); padding: 2px 1px; }

.lane-summary { display: flex; flex-direction: column; gap: 5px; }
.lane-summary .row { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--ink-2); }
.lane-summary .bar { height: 7px; border-radius: 4px; background: var(--lc, var(--ink-3)); opacity: 0.85; }
.lane-summary .n { margin-left: auto; color: var(--ink-3); font-variant-numeric: tabular-nums; }

content.content:
1	/* 脉络 · 依赖关系网 —— 应用逻辑
2	 * 核心约定（对应验收种子「关系跟随不丢失全局上下文」）：
3	 *  - 全图永远完整渲染；聚焦时只把无关图元降暗（opacity 0.13），永不隐藏、永不替换视图。
4	 *  - 「跟随」= 在相邻节点间行走，路径累计为面包屑；可回退、可换向、可分支。
5	 */
6	"use strict";
7	
8	/* ── 常量与索引 ─────────────────────────────────────────── */
9	const NW = 128, NH = 36;                 // 节点尺寸
10	const CW = 1690, CH = 1000;              // 画布坐标
11	const TYPE_NAME = { call: "同步调用", event: "事件", data: "数据读写" };
