28	function closure(start, nextMap) {
29	  const seen = new Set(), q = [start];
30	  while (q.length) {
31	    const x = q.shift();
32	    for (const y of nextMap[x]) if (!seen.has(y)) { seen.add(y); q.push(y); }
33	  }
34	  return seen;
35	}
36	const closureOut = id => closure(id, outTargets);  // 它（传递）依赖的一切
37	const closureIn  = id => closure(id, inSources);   // （传递）依赖它的一切 = 影响面
