126	/* ── 高亮与渲染 ─────────────────────────────────────────── */
127	function traceEdges() {
128	  const out = [];
129	  for (let i = 0; i + 1 < S.path.length; i++) {
130	    const a = S.path[i], b = S.path[i + 1];
131	    const e = edgeById[`${a}~${b}`] || edgeById[`${b}~${a}`];
132	    if (e) out.push(e);
133	  }
134	  return out;
135	}
