345	function followTo(id) {
346	  if (!byId[id]) return;
347	  S.selEdge = null;
348	  const cur = S.path[S.path.length - 1];
349	  if (cur && cur !== id && neighbors[cur].has(id)) S.path.push(id);   // 相邻：累计跟随
350	  else if (cur !== id) S.path = [id];                                  // 跳转：新起路径
351	  render();
352	}
