396	  const ng = ev.target.closest(".node-g");
397	  const hit = ev.target.closest(".edge-hit");
398	  if (ng) {
399	    const n = byId[ng.dataset.nid];
400	    showTip(ev, `<b>${n.name}</b><div class="tt-sub">${laneById[n.lane].name} · ${n.team}</div><div class="tt-sub">${n.desc}</div>`);
401	  } else if (hit) {
402	    const e = edgeById[hit.parentNode.dataset.eid];
403	    showTip(ev, `<b>${byId[e.f].name} ${TYPE_GLYPH[e.type]} ${byId[e.t].name}</b>
404	      <div class="tt-sub">${e.label} · ${TYPE_NAME[e.type]} · ${e.proto} · ${e.crit}</div>`);
405	  } else tooltip.hidden = true;
406	});
407	svg.addEventListener("mouseleave", () => { tooltip.hidden = true; });
408	svg.addEventListener("mouseover", ev => {
409	  const hit = ev.target.closest(".edge-hit");
410	  S.peek = hit ? hit.parentNode.dataset.eid : null; render();
411	});
