413	/* ── 搜索 ──────────────────────────────────────────────── */
414	const searchInput = document.getElementById("search");
415	const searchDrop = document.getElementById("search-drop");
416	function doSearch(q) {
417	  q = q.trim().toLowerCase();
418	  if (!q) { searchDrop.hidden = true; return; }
419	  const hits = NODES.filter(n => n.name.toLowerCase().includes(q) || n.id.includes(q) || n.desc.includes(q)).slice(0, 8);
420	  if (!hits.length) { searchDrop.hidden = true; return; }
421	  searchDrop.innerHTML = hits.map(n =>
422	    `<button data-nid="${n.id}"><span>${n.name}</span><span class="s-lane">${laneById[n.lane].name}</span></button>`).join("");
423	  searchDrop.hidden = false;
424	}
425	searchInput.addEventListener("input", () => doSearch(searchInput.value));
426	searchInput.addEventListener("keydown", ev => {
427	  if (ev.key === "Enter") {
428	    const first = searchDrop.querySelector("button");
429	    if (first) { followTo(first.dataset.nid); searchDrop.hidden = true; searchInput.value = ""; searchInput.blur(); }
430	  } else if (ev.key === "Escape") { searchDrop.hidden = true; searchInput.blur(); }
431	});
432	searchDrop.addEventListener("click", ev => {
433	  const b = ev.target.closest("button"); if (!b) return;
434	  followTo(b.dataset.nid);
435	  searchDrop.hidden = true; searchInput.value = "";
436	});
