438	/* ── 平移与缩放（viewBox） ─────────────────────────────── */
439	const VB = { x: 0, y: 0, w: CW, h: CH };
440	function applyVB() { svg.setAttribute("viewBox", `${VB.x} ${VB.y} ${VB.w} ${VB.h}`); }
441	function fitView() {
442	  const r = stage.getBoundingClientRect();
443	  const ar = r.width / Math.max(r.height, 1), dar = CW / CH;
444	  if (ar > dar) { VB.h = CH; VB.w = CH * ar; VB.x = (CW - VB.w) / 2; VB.y = 0; }
445	  else { VB.w = CW; VB.h = CW / ar; VB.x = 0; VB.y = (CH - VB.h) / 2; }
446	  applyVB();
447	}
448	function svgPoint(cx, cy) {
449	  const p = svg.createSVGPoint(); p.x = cx; p.y = cy;
450	  return p.matrixTransform(svg.getScreenCTM().inverse());
451	}
452	function zoomAt(cx, cy, f) {
453	  const w = Math.min(Math.max(VB.w * f, 320), CW * 3.2);
454	  f = w / VB.w;
455	  const pt = svgPoint(cx, cy);
456	  VB.x = pt.x - (pt.x - VB.x) * f; VB.y = pt.y - (pt.y - VB.y) * f;
457	  VB.w *= f; VB.h *= f; applyVB();
458	}
459	stage.addEventListener("wheel", ev => { ev.preventDefault(); zoomAt(ev.clientX, ev.clientY, ev.deltaY > 0 ? 1.12 : 1 / 1.12); }, { passive: false });
460	function zoomCenter(f) {
461	  const r = stage.getBoundingClientRect();
462	  zoomAt(r.left + r.width / 2, r.top + r.height / 2, f);
463	}
464	document.getElementById("btn-zin").addEventListener("click", () => zoomCenter(1 / 1.25));
465	document.getElementById("btn-zout").addEventListener("click", () => zoomCenter(1.25));
466	
467	let pan = null;
468	svg.addEventListener("pointerdown", ev => {
469	  if (ev.target.closest(".node-g") || ev.target.closest(".edge-hit")) return;
470	  pan = { x: ev.clientX, y: ev.clientY, vx: VB.x, vy: VB.y };
471	  svg.classList.add("panning"); svg.setPointerCapture(ev.pointerId);
472	});
473	svg.addEventListener("pointermove", ev => {
474	  if (!pan) return;
475	  const r = stage.getBoundingClientRect();
476	  VB.x = pan.vx - (ev.clientX - pan.x) * VB.w / r.width;
477	  VB.y = pan.vy - (ev.clientY - pan.y) * VB.h / r.height;
478	  applyVB();
479	});
480	svg.addEventListener("pointerup", () => { pan = null; svg.classList.remove("panning"); });
481	document.getElementById("btn-fit").addEventListener("click", fitView);
482	window.addEventListener("resize", fitView);
483	
484	/* ── 键盘 ──────────────────────────────────────────────── */
485	window.addEventListener("keydown", ev => {
486	  if (ev.target.tagName === "INPUT") return;
487	  if (ev.key === "Escape") resetAll();
488	  if (ev.key === "f" || ev.key === "F") fitView();
489	});
490	
491	/* ── 深链（#p=a>b>c&m=impact / #e=a~b）────── 同一交互代码路径 */
492	function syncHash() {
493	  let h = "";
494	  if (S.selEdge) h = `e=${S.selEdge}`;
495	  else if (S.path.length) h = `p=${S.path.join(">")}&m=${S.mode}`;
496	  try { history.replaceState(null, "", h ? "#" + h : location.pathname); } catch (_) { /* file:// 下可能受限 */ }
497	}
498	function parseHash() {
499	  const h = location.hash.slice(1);
500	  if (!h) return;
501	  const q = new URLSearchParams(h);
502	  const e = q.get("e");
503	  if (e && edgeById[e]) { S.selEdge = e; return; }
504	  const p = q.get("p");
505	  if (p) {
506	    const ids = p.split(">").map(s => s.trim()).filter(id => byId[id]);
507	    // 只保留可达的连续路径片段
508	    const ok = [];
509	    for (const id of ids) {
510	      const cur = ok[ok.length - 1];
511	      if (!cur || neighbors[cur].has(id) || id === cur) ok.push(id); else break;
512	    }
513	    if (ok.length) S.path = ok;
514	  }
515	  const m = q.get("m");
516	  if (["adj", "deps", "impact"].includes(m)) { S.mode = m; document.querySelectorAll(".modes button").forEach(b => b.classList.toggle("on", b.dataset.mode === m)); }
517	}
518	
519	/* ── 启动：同步构建 + 首屏即渲染，无加载态 ─────────────── */
520	buildDefs(); buildLanes(); buildEdges(); buildNodes();
521	parseHash();
522	fitView();
523	render();
