53	function buildDefs() {
54	  const defs = document.getElementById("defs");
55	  const mk = (id, color) => {
56	    const m = el("marker", { id, viewBox: "0 0 8 8", refX: 7, refY: 4, markerWidth: 8, markerHeight: 8, orient: "auto-start-reverse", markerUnits: "userSpaceOnUse" }, defs);
57	    el("path", { d: "M0,0.6 L8,4 L0,7.4 z", fill: color }, m);
58	  };
59	  mk("arr-call", "#3987e5"); mk("arr-event", "#d95926"); mk("arr-data", "#199e70"); mk("arr-trace", "#e8f1ff");
60	
61	  const pat = el("pattern", { id: "dots", width: 26, height: 26, patternUnits: "userSpaceOnUse" }, defs);
62	  el("circle", { cx: 1, cy: 1, r: 1, fill: "rgba(255,255,255,0.045)" }, pat);
