65	function edgePathD(e) {
66	  const a = byId[e.f], b = byId[e.t];
67	  const x1 = a.x + NW, y1 = a.y + NH / 2, x2 = b.x, y2 = b.y + NH / 2;
68	  if (b.x >= a.x + 40) {                       // 前向：水平贝塞尔
69	    const mx = (x1 + x2) / 2;
70	    return `M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}`;
71	  }
72	  if (b.x < a.x - 40) {                        // 回边：绕行画布下方
73	    const dip = Math.min(Math.max(a.y, b.y) + 110 + (e.id.length % 5) * 14, 972);
74	    return `M${x1},${y1} C${x1},${dip} ${x2},${dip} ${x2},${y2}`;
75	  }
76	  const side = x1 + 52 + (e.id.length % 3) * 14; // 同列：右侧绕行
77	  return `M${x1},${y1} C${side},${y1} ${side},${y2} ${x2},${y2}`;
78	}
