85	    grp.dataset.eid = e.id;
86	    const d = edgePathD(e);
87	    el("path", { class: `edge-line e-${e.type}`, d, "marker-end": `url(#arr-${e.type})` }, grp);
88	    el("path", { class: "edge-hit", d }, grp);
89	    edgeG[e.id] = grp;
90	  }
91	}
