101	    el("rect", { class: "node-accent", x: 0, y: 5, width: 3.5, height: NH - 10, fill: laneById[n.lane].accent, rx: 2 }, grp);
102	    const t = el("text", { class: "node-name", x: 12, y: NH / 2 + 4.5 }, grp);
