126	/* ── 高亮与渲染 ─────────────────────────────────────────── */
127	function traceEdges() {
128	  const out = [];
129	  for (let i = 0; i + 1 < S.path.length; i++) {
130	    const a = S.path[i], b = S.path[i + 1];
131	    const e = edgeById[`${a}~${b}`] || edgeById[`${b}~${a}`];
132	    if (e) out.push(e);
133	  }
134	  return out;
135	}
136	
137	function render() {
138	  const f = S.path[S.path.length - 1] || null;
139	  const hlN = new Set(), hlE = new Set();
140	  let dim = false;
141	
142	  if (S.selEdge) {
143	    dim = true;
144	    const e = edgeById[S.selEdge];
145	    hlN.add(e.f); hlN.add(e.t); hlE.add(e.id);
146	  } else if (f) {
147	    dim = true;
148	    hlN.add(f);
149	    let set;
150	    if (S.mode === "deps") set = closureOut(f);
151	    else if (S.mode === "impact") set = closureIn(f);
152	    else set = neighbors[f];
153	    set.forEach(n => hlN.add(n));
154	    for (const e of EDGES2) if (hlN.has(e.f) && hlN.has(e.t)) hlE.add(e.id);
155	  }
156	
157	  const traced = traceEdges();
158	  traced.forEach(e => { hlE.add(e.id); hlN.add(e.f); hlN.add(e.t); });
159	
160	  svg.classList.toggle("has-focus", dim);
161	  for (const n of NODES) {
162	    const g = nodeG[n.id];
163	    g.classList.toggle("focus", n.id === f);
164	    g.classList.toggle("hl", dim && hlN.has(n.id) && n.id !== f);
165	    g.classList.toggle("dim", dim && !hlN.has(n.id));
166	  }
167	  for (const e of EDGES2) {
168	    const g = edgeG[e.id];
169	    g.classList.toggle("trace", traced.some(t => t.id === e.id));
170	    g.classList.toggle("hl", dim && hlE.has(e.id) && !traced.some(t => t.id === e.id));
171	    g.classList.toggle("dim", dim && !hlE.has(e.id));
172	    g.classList.toggle("peek", S.peek === e.id);
173	    const onTrace = traced.some(t => t.id === e.id);
174	    g.querySelector(".edge-line").setAttribute("marker-end", onTrace ? "url(#arr-trace)" : `url(#arr-${e.type})`);
175	  }
176	  if (f) {
177	    focusRing.setAttribute("x", byId[f].x - 6); focusRing.setAttribute("y", byId[f].y - 6);
178	    focusRing.setAttribute("visibility", "visible");
179	  } else focusRing.setAttribute("visibility", "hidden");
180	
181	  renderTracebar(f);
182	  renderPanel(f);
183	  renderTopstats(f);
184	  syncHash();
185	}
