188	const tracebar = document.getElementById("tracebar");
189	function renderTracebar(f) {
190	  const sig = S.path.join(",");
191	  if (sig === traceSig) return;
192	  traceSig = sig;
193	  tracebar.innerHTML = "";
194	  tracebar.hidden = S.path.length === 0;
195	  if (!S.path.length) return;
196	  S.path.forEach((id, i) => {
197	    if (i > 0) {
198	      const a = S.path[i - 1], b = id;
199	      const e = edgeById[`${a}~${b}`] || edgeById[`${b}~${a}`];
200	      const forward = e && e.f === a;
201	      const sep = document.createElement("span");
202	      sep.className = "crumb-sep";
203	      sep.style.color = e ? { call: "#3987e5", event: "#d95926", data: "#199e70" }[e.type] : "var(--ink-3)";
204	      sep.textContent = forward ? "─▸" : "◂─";
205	      sep.title = e ? `${e.f} 依赖 ${e.t}（${TYPE_NAME[e.type]}）` : "";
206	      tracebar.appendChild(sep);
207	    }
208	    const btn = document.createElement("button");
209	    btn.className = "crumb" + (id === f ? " cur" : "");
210	    btn.textContent = byId[id].name;
211	    btn.title = id === f ? "当前聚焦" : "回到这一步（保留前缀）";
212	    btn.addEventListener("click", () => { S.path = S.path.slice(0, i + 1); S.selEdge = null; render(); });
213	    tracebar.appendChild(btn);
214	  });
215	  const meta = document.createElement("span");
216	  meta.className = "crumb-meta";
217	  meta.textContent = `影响闭包 ${closureIn(f).size} · 依赖闭包 ${closureOut(f).size}`;
218	  tracebar.appendChild(meta);
219	  const clear = document.createElement("button");
220	  clear.className = "btn"; clear.textContent = "重置";
221	  clear.addEventListener("click", resetAll);
222	  tracebar.appendChild(clear);
223	}
