351	/* ── 交互：跟随 ────────────────────────────────────────── */
352	function followTo(id) {
353	  if (!byId[id]) return;
354	  S.selEdge = null;
355	  const cur = S.path[S.path.length - 1];
356	  if (cur && cur !== id && neighbors[cur].has(id)) S.path.push(id);   // 相邻：累计跟随
357	  else if (cur !== id) S.path = [id];                                  // 跳转：新起路径
358	  render();
359	}
360	function resetAll() { S.path = []; S.selEdge = null; S.mode = "adj"; render(); }
361	function setMode(m) {
362	  S.mode = m;
363	  document.querySelectorAll(".modes button").forEach(b => b.classList.toggle("on", b.dataset.mode === m));
364	  render();
365	}
