367	/* 事件委托（面板内按钮） */
368	panel.addEventListener("click", ev => {
369	  const b = ev.target.closest("button"); if (!b) return;
370	  const nid = b.dataset.nid, eid = b.dataset.eid;
371	  if (nid) followTo(nid);
372	  else if (eid) { S.selEdge = eid; render(); }   // 保留跟随路径：查看关系不丢弃全局上下文
373	});
374	panel.addEventListener("mouseover", ev => {
375	  const b = ev.target.closest("button"); if (!b) return;
376	  S.peek = b.dataset.eid || null; render();
377	});
378	panel.addEventListener("mouseout", () => { if (S.peek) { S.peek = null; render(); } });
