383	/* SVG 上的点击（拖拽平移后的 click 需抑制） */
384	let panMoved = false;
385	svg.addEventListener("click", ev => {
386	  if (panMoved) { panMoved = false; return; }
387	  const ng = ev.target.closest(".node-g");
388	  const hit = ev.target.closest(".edge-hit");
389	  if (ng) { followTo(ng.dataset.nid); return; }
390	  if (hit) { S.selEdge = hit.parentNode.dataset.eid; render(); return; }
391	  if (S.selEdge) { S.selEdge = null; render(); }   // 点空白处 = 取消关系选中（跟随路径保留）
392	});
