        <button data-nid="${b.id}" data-eid="">${b.name}</button>
      </div>
      <p class="pdesc">${e.label} —— ${e.desc}</p>
    </div>
    <div class="chips">
      <span class="chip">类型 · ${TYPE_NAME[e.type]}</span>
      <span class="chip">协议 · ${e.proto}</span>
