    </div>
    <div class="statrow grid3" style="margin-top:14px">
      <div><b>${outEdges[a.id].length}</b><span>${a.name} 的依赖</span></div>
      <div><b>${inEdges[b.id].length}</b><span>${b.name} 被依赖</span></div>
