    <p class="pnote" style="margin-top:12px">关系即内容：${TYPE_NAME[e.type]}${e.type === "event" ? "意味着解耦——故障传播慢一拍但同样到达" : e.type === "data" ? "意味着数据契约——模式变更需双向协同" : "意味着同步依赖——可用性直接受下游牵连"}。</p>`;
}

/* ── 顶栏统计 ──────────────────────────────────────────── */
const topstats = document.getElementById("topstats");
function renderTopstats(f) {
  topstats.innerHTML = f
    ? `聚焦 <b>${byId[f].name}</b> · ${NODES.length} 节点 · ${EDGES2.length} 关系`
    : `<b>${NODES.length}</b> 节点 · <b>${EDGES2.length}</b> 关系 · <b>${LANES.length}</b> 层`;
}

/* ── 交互：跟随 ────────────────────────────────────────── */
function followTo(id) {
  if (!byId[id]) return;
  S.selEdge = null;
  const cur = S.path[S.path.length - 1];
  if (cur && cur !== id && neighbors[cur].has(id)) S.path.push(id);   // 相邻：累计跟随
  else if (cur !== id) S.path = [id];                                  // 跳转：新起路径
  render();
}
function resetAll() { S.path = []; S.selEdge = null; S.mode = "adj"; render(); }
function setMode(m) {
  S.mode = m;
  document.querySelectorAll(".modes button").forEach(b => b.classList.toggle("on", b.dataset.mode === m));
  render();
}

/* 事件委托（面板内按钮） */
panel.addEventListener("click", ev => {
  const b = ev.target.closest("button"); if (!b) return;
  const nid = b.dataset.nid, eid = b.dataset.eid;
  if (nid) followTo(nid);
  else if (eid) { S.selEdge = eid; render(); }   // 保留跟随路径：查看关系不丢弃全局上下文
});
panel.addEventListener("mouseover", ev => {
  const b = ev.target.closest("button"); if (!b) return;
  S.peek = b.dataset.eid || null; render();
});
panel.addEventListener("mouseout", () => { if (S.peek) { S.peek = null; render(); } });

document.querySelectorAll(".modes button").forEach(b => b.addEventListener("click", () => setMode(b.dataset.mode)));
document.getElementById("btn-reset").addEventListener("click", resetAll);

/* SVG 上的点击（拖拽平移后的 click 需抑制） */
let panMoved = false;
svg.addEventListener("click", ev => {
  if (panMoved) { panMoved = false; return; }
  const ng = ev.target.closest(".node-g");
  const hit = ev.target.closest(".edge-hit");
  if (ng) { followTo(ng.dataset.nid); return; }
  if (hit) { S.selEdge = hit.parentNode.dataset.eid; render(); return; }
  if (S.selEdge) { S.selEdge = null; render(); }   // 点空白处 = 取消关系选中（跟随路径保留）
});

/* ── 提示气泡 ──────────────────────────────────────────── */
const tooltip = document.getElementById("tooltip");
function showTip(ev, html) {
  tooltip.innerHTML = html; tooltip.hidden = false;
  const r = stage.getBoundingClientRect();
  let x = ev.clientX - r.left + 14, y = ev.clientY - r.top + 14;
  x = Math.min(x, r.width - tooltip.offsetWidth - 8);
  y = Math.min(y, r.height - tooltip.offsetHeight - 8);
  tooltip.style.left = x + "px"; tooltip.style.top = y + "px";
}
svg.addEventListener("mousemove", ev => {
  const ng = ev.target.closest(".node-g");
  const hit = ev.target.closest(".edge-hit");
  if (ng) {
    const n = byId[ng.dataset.nid];
    showTip(ev, `<b>${n.name}</b><div class="tt-sub">${laneById[n.lane].name} · ${n.team}</div><div class="tt-sub">${n.desc}</div>`);
  } else if (hit) {
    const e = edgeById[hit.parentNode.dataset.eid];
    showTip(ev, `<b>${byId[e.f].name} ${TYPE_GLYPH[e.type]} ${byId[e.t].name}</b>
      <div class="tt-sub">${e.label} · ${TYPE_NAME[e.type]} · ${e.proto} · ${e.crit}</div>`);
  } else tooltip.hidden = true;
});
svg.addEventListener("mouseleave", () => { tooltip.hidden = true; });
svg.addEventListener("mouseover", ev => {
  const hit = ev.target.closest(".edge-hit");
  S.peek = hit ? hit.parentNode.dataset.eid : null; render();
});

/* ── 搜索 ──────────────────────────────────────────────── */
const searchInput = document.getElementById("search");
const searchDrop = document.getElementById("search-drop");
function doSearch(q) {
  q = q.trim().toLowerCase();
  if (!q) { searchDrop.hidden = true; return; }
  const hits = NODES.filter(n => n.name.toLowerCase().includes(q) || n.id.includes(q) || n.desc.includes(q)).slice(0, 8);
  if (!hits.length) { searchDrop.hidden = true; return; }
  searchDrop.innerHTML = hits.map(n =>
    `<button data-nid="${n.id}"><span>${n.name}</span><span class="s-lane">${laneById[n.lane].name}</span></button>`).join("");
  searchDrop.hidden = false;
}
searchInput.addEventListener("input", () => doSearch(searchInput.value));
searchInput.addEventListener("keydown", ev => {
  if (ev.key === "Enter") {
    const first = searchDrop.querySelector("button");
    if (first) { followTo(first.dataset.nid); searchDrop.hidden = true; searchInput.value = ""; searchInput.blur(); }
  } else if (ev.key === "Escape") { searchDrop.hidden = true; searchInput.blur(); }
});
searchDrop.addEventListener("click", ev => {
  const b = ev.target.closest("button"); if (!b) return;
  followTo(b.dataset.nid);
  searchDrop.hidden = true; searchInput.value = "";
});

/* ── 平移与缩放（viewBox） ─────────────────────────────── */
const VB = { x: 0, y: 0, w: CW, h: CH };
function applyVB() { svg.setAttribute("viewBox", `${VB.x} ${VB.y} ${VB.w} ${VB.h}`); }
function fitView() {
  const r = stage.getBoundingClientRect();
  const ar = r.width / Math.max(r.height, 1), dar = CW / CH;
  if (ar > dar) { VB.h = CH; VB.w = CH * ar; VB.x = (CW - VB.w) / 2; VB.y = 0; }
  else { VB.w = CW; VB.h = CW / ar; VB.x = 0; VB.y = (CH - VB.h) / 2; }
  applyVB();
}
function svgPoint(cx, cy) {
  const p = svg.createSVGPoint(); p.x = cx; p.y = cy;
  return p.matrixTransform(svg.getScreenCTM().inverse());
}
function zoomAt(cx, cy, f) {
  const w = Math.min(Math.max(VB.w * f, 320), CW * 3.2);
  f = w / VB.w;
  const pt = svgPoint(cx, cy);
  VB.x = pt.x - (pt.x - VB.x) * f; VB.y = pt.y - (pt.y - VB.y) * f;
  VB.w *= f; VB.h *= f; applyVB();
}
stage.addEventListener("wheel", ev => { ev.preventDefault(); zoomAt(ev.clientX, ev.clientY, ev.deltaY > 0 ? 1.12 : 1 / 1.12); }, { passive: false });
function zoomCenter(f) {
  const r = stage.getBoundingClientRect();
  zoomAt(r.left + r.width / 2, r.top + r.height / 2, f);
}
document.getElementById("btn-zin").addEventListener("click", () => zoomCenter(1 / 1.25));
document.getElementById("btn-zout").addEventListener("click", () => zoomCenter(1.25));

let pan = null;
svg.addEventListener("pointerdown", ev => {
  if (ev.target.closest(".node-g") || ev.target.closest(".edge-hit")) return;
  pan = { x: ev.clientX, y: ev.clientY, vx: VB.x, vy: VB.y };
  svg.classList.add("panning"); svg.setPointerCapture(ev.pointerId);
});
svg.addEventListener("pointermove", ev => {
  if (!pan) return;
  if (Math.abs(ev.clientX - pan.x) + Math.abs(ev.clientY - pan.y) > 3) panMoved = true;
  const r = stage.getBoundingClientRect();
  VB.x = pan.vx - (ev.clientX - pan.x) * VB.w / r.width;
  VB.y = pan.vy - (ev.clientY - pan.y) * VB.h / r.height;
  applyVB();
});
svg.addEventListener("pointerup", () => { pan = null; svg.classList.remove("panning"); });
document.getElementById("btn-fit").addEventListener("click", fitView);
window.addEventListener("resize", fitView);

/* ── 键盘 ──────────────────────────────────────────────── */
window.addEventListener("keydown", ev => {
  if (ev.target.tagName === "INPUT") return;
  if (ev.key === "Escape") resetAll();
  if (ev.key === "f" || ev.key === "F") fitView();
});

/* ── 深链（#p=a>b>c&m=impact / #e=a~b）────── 同一交互代码路径 */
function syncHash() {
  let h = "";
  if (S.selEdge) h = `e=${S.selEdge}`;
  else if (S.path.length) h = `p=${S.path.join(">")}&m=${S.mode}`;
  try { history.replaceState(null, "", h ? "#" + h : location.pathname); } catch (_) { /* file:// 下可能受限 */ }
}
function parseHash() {
  const h = location.hash.slice(1);
  if (!h) return;
  const q = new URLSearchParams(h);
  const e = q.get("e");
  if (e && edgeById[e]) { S.selEdge = e; return; }
  const p = q.get("p");
  if (p) {
    const ids = p.split(">").map(s => s.trim()).filter(id => byId[id]);
    // 只保留可达的连续路径片段
    const ok = [];
    for (const id of ids) {
      const cur = ok[ok.length - 1];
      if (!cur || neighbors[cur].has(id) || id === cur) ok.push(id); else break;
    }
    if (ok.length) S.path = ok;
  }
  const m = q.get("m");
  if (["adj", "deps", "impact"].includes(m)) { S.mode = m; document.querySelectorAll(".modes button").forEach(b => b.classList.toggle("on", b.dataset.mode === m)); }
}

/* ── 启动：同步构建 + 首屏即渲染，无加载态 ─────────────── */
buildDefs(); buildLanes(); buildEdges(); buildNodes();
parseHash();
fitView();
render();

/* 脉络 · 自检 —— 在真实浏览器中对已加载的应用执行交互全链路断言。
 * 打开 selftest.html 即自动运行；结果渲染到页面左上角面板，并写入 window.__SELFTEST__ 与 console。 */
"use strict";

window.addEventListener("load", () => {
  const R = [];
  const $ = s => document.querySelector(s);
  const $$ = s => [...document.querySelectorAll(s)];
  const assert = (cond, msg) => { if (!cond) throw new Error(msg); };
  const txt = el => (el ? el.textContent.trim() : "");

  function t(name, fn) {
    try { fn(); R.push({ name, pass: true, info: "" }); }
    catch (e) { R.push({ name, pass: false, info: String(e && e.message || e) }); }
  }
  const counts = () => ({
    focus: $$(".node-g.focus").length, hl: $$(".node-g.hl").length, dim: $$(".node-g.dim").length,
    trace: $$(".edge-g.trace").length, hlE: $$(".edge-g.hl").length,
  });

  /* 1. 首屏即用：无加载态，同步渲染 */
  t("首屏同步渲染：33 节点 / 58 关系图元", () => {
    assert($$(".node-g").length === 33, `node-g=${$$(".node-g").length}`);
    assert($$(".edge-g").length === 58, `edge-g=${$$(".edge-g").length}`);
    assert(txt($("#topstats")).includes("33 节点 · 58 关系 · 6 层"), txt($("#topstats")));
  });
  t("首屏面板 = 全局概览（无加载态文案）", () => {
    assert(txt($("#panel-body .pkick")) === "全局概览", txt($("#panel-body .pkick")));
    assert(!/加载|loading/i.test(document.body.textContent), "出现加载态文案");
  });
  t("数据完整性：边端点有效、无重复、类型与关键性计数", () => {
    assert(EDGES2.every(e => byId[e.f] && byId[e.t]), "存在未知端点");
    assert(new Set(EDGES2.map(e => e.id)).size === 58, "边 id 重复");
    const c = t => EDGES2.filter(e => e.type === t).length;
    assert(c("call") === 34 && c("event") === 8 && c("data") === 16, `call=${c("call")} event=${c("event")} data=${c("data")}`);
    assert(EDGES2.filter(e => e.crit === "P0").length === 27, "P0 计数不符");
  });
  t("闭包计算：订单 16/8，消息总线 18/0（环不重复计自身）", () => {
    assert(closureOut("order").size === 16, `order 依赖闭包=${closureOut("order").size}`);
    assert(closureIn("order").size === 8, `order 影响闭包=${closureIn("order").size}`);
    assert(closureIn("mq").size === 18, `mq 影响闭包=${closureIn("mq").size}`);
    assert(closureOut("mq").size === 0, "mq 不应有出边依赖");
  });

  /* 2. 聚焦：全局上下文保留 */
  t("点击聚焦 订单服务：8 直依 / 3 被依 / 16 / 8，面板为节点卡", () => {
    followTo("order");
    assert(txt($("#panel-body h2")) === "订单服务", txt($("#panel-body h2")));
    const v = $$("#panel-body .statrow b").map(b => b.textContent);
    assert(v.join(",") === "8,3,16,8", v.join(","));
  });
  t("高亮：1 聚焦 + 11 加亮 + 21 降暗 = 33，无任何节点被隐藏", () => {
    const c = counts();
    assert(c.focus === 1 && c.hl === 11 && c.dim === 21, JSON.stringify(c));
    assert($$(".node-g").every(g => getComputedStyle(g).display !== "none"), "存在 display:none 节点");
    assert(getComputedStyle(nodeG.product).opacity === "0.13", `非相邻节点 opacity=${getComputedStyle(nodeG.product).opacity}`);
    assert($("#graph").classList.contains("has-focus"), "svg 缺少 has-focus");
  });

  /* 3. 跟随：路径累计与方向语义 */
  t("跟随 订单→消息总线：路径累计、1 条跟随边、面包屑 ─▸", () => {
    $("#panel-body .rel[data-nid=\"mq\"]").click();
    assert(S.path.join(">") === "order>mq", S.path.join(">"));
    const crumbs = $$("#tracebar .crumb").map(b => b.textContent);
    assert(crumbs.join("|") === "订单服务|消息总线", crumbs.join("|"));
    assert(counts().trace === 1, `trace=${counts().trace}`);
    assert($(".crumb-sep").textContent === "─▸", $(".crumb-sep").textContent);
    assert(txt($(".crumb-meta")).includes("影响闭包 18"), txt($(".crumb-meta")));
  });
  t("逆方向跟随 消息总线←通知中心：分隔符 ◂─（真实依赖方向）", () => {
    followTo("notify");
    assert(S.path.length === 3, "路径长度应为 3");
    assert(counts().trace === 2, `trace=${counts().trace}`);
    const seps = $$(".crumb-sep").map(s => s.textContent);
    assert(seps.join("|") === "─▸|◂─", seps.join("|"));
  });
  t("面包屑回退：点击第一步 → 路径截断为前缀", () => {
    $$("#tracebar .crumb")[0].click();
    assert(S.path.length === 1 && S.path[0] === "order", S.path.join(">"));
  });

  /* 4. 透镜：闭包模式 */
  t("影响闭包（订单）：8 节点加亮；依赖闭包：16 节点加亮", () => {
    setMode("impact");
    let c = counts();
    assert(c.hl === 8 && c.focus === 1, `impact hl=${c.hl}`);
    assert($$('.modes button[data-mode="impact"]').classList.contains("on"), "模式按钮未同步");
    setMode("deps");
    c = counts();
    assert(c.hl === 16 && c.focus === 1, `deps hl=${c.hl}`);
    setMode("adj");
  });
  t("影响闭包（消息总线）：18 节点加亮（枢纽影响面）", () => {
    resetAll(); followTo("mq"); setMode("impact");
    const c = counts();
    assert(c.hl === 18 && c.focus === 1, `hl=${c.hl}`);
    assert(!nodeG.order.classList.contains("dim"), "订单服务应在消息总线的影响面内");
    setMode("adj"); resetAll();
  });

  /* 5. 关系是一等对象：选边不清空跟随路径 */
  t("选中关系 order~inventory：关系卡渲染，跟随路径保留", () => {
    followTo("order"); followTo("mq"); followTo("notify");
    $('.edge-g[data-eid="order~inventory"] .edge-hit').dispatchEvent(new MouseEvent("click", { bubbles: true }));
    assert(S.selEdge === "order~inventory", `selEdge=${S.selEdge}`);
    assert(S.path.length === 3, "选边不应清空跟随路径");
    assert(txt($("#panel-body .pkick")).startsWith("关系 ·"), txt($("#panel-body .pkick")));
    assert(txt($("#panel-body")).includes("锁定库存") && txt($("#panel-body")).includes("gRPC"), "关系卡字段缺失");
    assert($$("#tracebar .crumb").length === 3, "面包屑应仍在");
  });

  /* 6. 搜索与重置 */
  t("搜索「库存」回车：跟随到 库存服务，路径重置为新路径", () => {
    resetAll();
    const inp = $("#search");
    inp.value = "库存";
    inp.dispatchEvent(new Event("input", { bubbles: true }));
    assert(!$("#search-drop").hidden, "下拉未出现");
    assert($("#search-drop").innerHTML.includes("库存服务"), "下拉缺少 库存服务");
    inp.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
    assert(S.path.length === 1 && S.path[0] === "inventory", S.path.join(">"));
    assert(txt($("#panel-body h2")) === "库存服务", txt($("#panel-body h2")));
  });
  t("Esc 重置：回到全局概览，全部图元恢复正常", () => {
    window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape" }));
    assert(S.path.length === 0 && S.selEdge === null, "状态未清空");
    assert(!$("#graph").classList.contains("has-focus"), "has-focus 未移除");
    assert($("#tracebar").hidden === true, "面包屑未隐藏");
    assert(counts().dim === 0 && counts().hl === 0 && counts().focus === 0, JSON.stringify(counts()));
    assert(txt($("#panel-body .pkick")) === "全局概览", "面板未回到概览");
  });

  /* 7. 深链与视图 */
  t("深链 #p=order>mq>notify：恢复三步跟随", () => {
    location.hash = "#p=order>mq>notify";
    parseHash();
    assert(S.path.join(">") === "order>mq>notify", S.path.join(">"));
    history.replaceState(null, "", location.pathname);
    resetAll();
  });
  t("缩放与适应视图：viewBox 变化并可复位", () => {
    fitView();
    const w0 = VB.w;
    zoomCenter(1 / 1.25);
    assert(Math.abs(VB.w - w0 * 1.25) < w0 * 0.01, `VB.w ${w0} → ${VB.w}`);
    fitView();
    assert(Math.abs(VB.w - w0) < 0.01, "fitView 未复位");
  });
  t("外部节点标记：4 个 ext 节点带虚线边框样式类", () => {
    assert($$(".node-g.ext").length === 4, `ext=${$$(".node-g.ext").length}`);
  });

  /* 汇总渲染 */
  const pass = R.filter(r => r.pass).length, total = R.length;
  window.__SELFTEST__ = { pass, total, failures: R.filter(r => !r.pass) };
  const st = document.createElement("style");
  st.textContent = `
    #selftest{position:fixed;top:68px;left:12px;z-index:200;width:480px;max-height:72vh;overflow:auto;
      background:rgba(13,21,38,.96);border:1px solid rgba(255,255,255,.12);border-radius:12px;
      padding:12px 14px;font:12px/1.6 Consolas,monospace;color:#eef3fb;box-shadow:0 12px 32px rgba(0,0,0,.5)}
    #selftest h2{font-size:13px;margin-bottom:8px;font-family:system-ui}
    #selftest .sum{font-weight:700;font-size:13px;margin-bottom:8px;font-family:system-ui}
    #selftest .ok{color:#6fd0a8}#selftest .bad{color:#ff9b9b}#selftest .info{color:#8b98ab}
    #selftest div.row{padding:1px 0;border-bottom:1px dashed rgba(255,255,255,.06)}`;
  document.head.appendChild(st);
  const box = document.createElement("div");
  box.id = "selftest";
