    assert(!$("#search-drop").hidden, "下拉未出现");
    assert($("#search-drop").innerHTML.includes("库存服务"), "下拉缺少 库存服务");
    inp.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
    assert(S.path.length === 1 && S.path[0] === "inventory", S.path.join(">"));
    assert(txt($("#panel-body h2")) === "库存服务", txt($("#panel-body h2")));
  });
  t("Esc 重置：回到全局概览，全部图元恢复正常", () => {
    window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape" }));
    assert(S.path.length === 0 && S.selEdge === null, "状态未清空");
    assert(!$("#graph").classList.contains("has-focus"), "has-focus 未移除");
    assert($("#tracebar").hidden === true, "面包屑未隐藏");
    assert(counts().dim === 0 && counts().hl === 0 && counts().focus === 0, JSON.stringify(counts()));
    assert(txt($("#panel-body .pkick")) === "全局概览", "面板未回到概览");
  });

  /* 7. 深链与视图 */
  t("深链 #p=order>mq>notify：恢复三步跟随", () => {
    location.hash = "#p=order>mq>notify";
    parseHash();
    assert(S.path.join(">") === "order>mq>notify", S.path.join(">"));
    history.replaceState(null, "", location.pathname);
    resetAll();
  });
  t("缩放与适应视图：viewBox 变化并可复位", () => {
    fitView();
    const w0 = VB.w;
    zoomCenter(1 / 1.25);   // 放大：viewBox 宽度缩小为 0.8 倍
    assert(Math.abs(VB.w - w0 * 0.8) < w0 * 0.01, `VB.w ${w0} → ${VB.w}`);
    fitView();
    assert(Math.abs(VB.w - w0) < 0.01, "fitView 未复位");
  });
  t("外部节点标记：4 个 ext 节点带虚线边框样式类", () => {
    assert($$(".node-g.ext").length === 4, `ext=${$$(".node-g.ext").length}`);
  });

  /* 汇总渲染 */
  const pass = R.filter(r => r.pass).length, total = R.length;
  window.__SELFTEST__ = { pass, total, failures: R.filter(r => !r.pass) };
  const st = document.createElement("style");
  st.textContent = `
    #selftest{position:fixed;top:68px;left:12px;z-index:200;width:480px;max-height:72vh;overflow:auto;
      background:rgba(13,21,38,.96);border:1px solid rgba(255,255,255,.12);border-radius:12px;
      padding:12px 14px;font:12px/1.6 Consolas,monospace;color:#eef3fb;box-shadow:0 12px 32px rgba(0,0,0,.5)}
    #selftest h2{font-size:13px;margin-bottom:8px;font-family:system-ui}
    #selftest .sum{font-weight:700;font-size:13px;margin-bottom:8px;font-family:system-ui}
    #selftest .ok{color:#6fd0a8}#selftest .bad{color:#ff9b9b}#selftest .info{color:#8b98ab}
    #selftest div.row{padding:1px 0;border-bottom:1px dashed rgba(255,255,255,.06)}`;
  document.head.appendChild(st);
  const box = document.createElement("div");
  box.id = "selftest";
  box.innerHTML = `<h2>自检 · 关系跟随全链路</h2>
    <div class="sum ${pass === total ? "ok" : "bad"}">${pass === total ? "✔ 全部通过" : "✘ 存在失败"} — ${pass}/${total}</div>` +
    R.map(r => `<div class="row"><span class="${r.pass ? "ok" : "bad"}">${r.pass ? "✔" : "✘"}</span> ${r.name}${r.pass ? "" : `<div class="info">↳ ${r.info}</div>`}</div>`).join("");
  document.body.appendChild(box);
  console.log(`[selftest] ${pass}/${total} PASS`, window.__SELFTEST__.failures);
});

content.content:
1	/* 脉络 · 依赖关系网 —— 应用逻辑
2	 * 核心约定（对应验收种子「关系跟随不丢失全局上下文」）：
3	 *  - 全图永远完整渲染；聚焦时只把无关图元降暗（opacity 0.13），永不隐藏、永不替换视图。
4	 *  - 「跟随」= 在相邻节点间行走，路径累计为面包屑；可回退、可换向、可分支。
5	 */
6	"use strict";
7	
8	/* ── 常量与索引 ─────────────────────────────────────────── */
9	const NW = 128, NH = 36;                 // 节点尺寸
10	const CW = 1690, CH = 1000;              // 画布坐标
11	const TYPE_NAME = { call: "同步调用", event: "事件", data: "数据读写" };
12	const TYPE_GLYPH = { call: "─▸", event: "⤍", data: "⇢" };
13	const CRIT_ORDER = { P0: 0, P1: 1, P2: 2 };
14	
15	const byId = Object.fromEntries(NODES.map(n => [n.id, n]));
16	const laneById = Object.fromEntries(LANES.map(l => [l.id, l]));
17	const EDGES2 = EDGES.map(e => ({ ...e, id: `${e.f}~${e.t}` }));
18	const edgeById = Object.fromEntries(EDGES2.map(e => [e.id, e]));
19	
20	const outEdges = {}, inEdges = {}, outTargets = {}, inSources = {}, neighbors = {};
21	NODES.forEach(n => { outEdges[n.id] = []; inEdges[n.id] = []; outTargets[n.id] = new Set(); inSources[n.id] = new Set(); neighbors[n.id] = new Set(); });
22	EDGES2.forEach(e => {
23	  outEdges[e.f].push(e); inEdges[e.t].push(e);
24	  outTargets[e.f].add(e.t); inSources[e.t].add(e.f);
25	  neighbors[e.f].add(e.t); neighbors[e.t].add(e.f);
26	});
27	
28	function closure(start, nextMap) {
29	  const seen = new Set(), q = [start];
30	  while (q.length) {
31	    const x = q.shift();
32	    for (const y of nextMap[x]) if (!seen.has(y)) { seen.add(y); q.push(y); }
33	  }
34	  return seen;
35	}
36	const closureOut = id => { const s = closure(id, outTargets); s.delete(id); return s; };  // 它（传递）依赖的一切（环回到自身时不含自身）
37	const closureIn  = id => { const s = closure(id, inSources); s.delete(id); return s; };   // （传递）依赖它的一切 = 影响面
38	
39	/* ── 状态 ──────────────────────────────────────────────── */
40	const S = { path: [], mode: "adj", selEdge: null, peek: null };
41	
42	/* ── SVG 构建 ──────────────────────────────────────────── */
43	const svg = document.getElementById("graph");
44	const stage = document.getElementById("stage");
45	const NS = "http://www.w3.org/2000/svg";
46	const el = (tag, attrs, parent) => {
47	  const d = document.createElementNS(NS, tag);
48	  for (const k in attrs) d.setAttribute(k, attrs[k]);
49	  if (parent) parent.appendChild(d);
50	  return d;
51	};
52	
53	function buildDefs() {
54	  const defs = document.getElementById("defs");
55	  const mk = (id, color) => {
56	    const m = el("marker", { id, viewBox: "0 0 8 8", refX: 7, refY: 4, markerWidth: 8, markerHeight: 8, orient: "auto-start-reverse", markerUnits: "userSpaceOnUse" }, defs);
57	    el("path", { d: "M0,0.6 L8,4 L0,7.4 z", fill: color }, m);
58	  };
59	  mk("arr-call", "#3987e5"); mk("arr-event", "#d95926"); mk("arr-data", "#199e70"); mk("arr-trace", "#e8f1ff");
60	
61	  const pat = el("pattern", { id: "dots", width: 26, height: 26, patternUnits: "userSpaceOnUse" }, defs);
62	  el("circle", { cx: 1, cy: 1, r: 1, fill: "rgba(255,255,255,0.045)" }, pat);
63	}
64	
65	function edgePathD(e) {
66	  const a = byId[e.f], b = byId[e.t];
67	  const x1 = a.x + NW, y1 = a.y + NH / 2, x2 = b.x, y2 = b.y + NH / 2;
68	  if (b.x >= a.x + 40) {                       // 前向：水平贝塞尔
69	    const mx = (x1 + x2) / 2;
70	    return `M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}`;
71	  }
72	  if (b.x < a.x - 40) {                        // 回边：绕行画布下方
73	    const dip = Math.min(Math.max(a.y, b.y) + 110 + (e.id.length % 5) * 14, 972);
74	    return `M${x1},${y1} C${x1},${dip} ${x2},${dip} ${x2},${y2}`;
75	  }
76	  const side = x1 + 52 + (e.id.length % 3) * 14; // 同列：右侧绕行
77	  return `M${x1},${y1} C${side},${y1} ${side},${y2} ${x2},${y2}`;
78	}
79	
80	const edgeG = {};
81	function buildEdges() {
82	  const g = document.getElementById("g-edges");
83	  for (const e of EDGES2) {
84	    const grp = el("g", { class: `edge-g ${e.type}`.trim() }, g);
85	    grp.dataset.eid = e.id;
86	    const d = edgePathD(e);
87	    el("path", { class: `edge-line e-${e.type}`, d, "marker-end": `url(#arr-${e.type})` }, grp);
88	    el("path", { class: "edge-hit", d }, grp);
89	    edgeG[e.id] = grp;
90	  }
91	}
92	
93	const nodeG = {};
94	function buildNodes() {
95	  const g = document.getElementById("g-nodes");
96	  for (const n of NODES) {
97	    const grp = el("g", { class: "node-g", transform: `translate(${n.x},${n.y})` }, g);
98	    grp.dataset.nid = n.id;
99	    if (n.lane === "ext") grp.classList.add("ext");
100	    el("rect", { class: "node-box", x: 0, y: 0, width: NW, height: NH }, grp);
101	    el("rect", { class: "node-accent", x: 0, y: 5, width: 3.5, height: NH - 10, fill: laneById[n.lane].accent, rx: 2 }, grp);
102	    const t = el("text", { class: "node-name", x: 12, y: NH / 2 + 4.5 }, grp);
103	    t.textContent = n.name;
104	    nodeG[n.id] = grp;
105	  }
106	}
107	
108	function buildLanes() {
109	  const g = document.getElementById("g-lanes");
110	  el("rect", { x: 0, y: 0, width: CW, height: CH, fill: "url(#dots)" }, g);
111	  for (const l of LANES) {
112	    el("line", { class: "lane-sep", x1: l.x - 22, y1: 52, x2: l.x - 22, y2: 982 }, g);
113	    const count = NODES.filter(n => n.lane === l.id).length;
114	    const t = el("text", { class: "lane-name", x: l.x + 1, y: 34 }, g);
115	    t.textContent = l.name;
116	    const c = el("text", { class: "lane-count", x: l.x + 1, y: 50 }, g);
117	    c.textContent = `× ${count}`;
118	  }
119	}
120	
121	const focusRing = (() => {
122	  const r = el("rect", { class: "focus-ring", width: NW + 12, height: NH + 12, x: -6, y: -6, rx: 13, visibility: "hidden" }, document.getElementById("g-trace"));
123	  return r;
124	})();
125	
126	/* ── 高亮与渲染 ─────────────────────────────────────────── */
127	function traceEdges() {
128	  const out = [];
129	  for (let i = 0; i + 1 < S.path.length; i++) {
130	    const a = S.path[i], b = S.path[i + 1];
131	    const e = edgeById[`${a}~${b}`] || edgeById[`${b}~${a}`];
132	    if (e) out.push(e);
133	  }
134	  return out;
135	}
136	
137	function render() {
138	  const f = S.path[S.path.length - 1] || null;
139	  const hlN = new Set(), hlE = new Set();
140	  let dim = false;
141	
142	  if (S.selEdge) {
143	    dim = true;
144	    const e = edgeById[S.selEdge];
145	    hlN.add(e.f); hlN.add(e.t); hlE.add(e.id);
146	  } else if (f) {
147	    dim = true;
148	    hlN.add(f);
149	    let set;
150	    if (S.mode === "deps") set = closureOut(f);
151	    else if (S.mode === "impact") set = closureIn(f);
152	    else set = neighbors[f];
153	    set.forEach(n => hlN.add(n));
154	    for (const e of EDGES2) if (hlN.has(e.f) && hlN.has(e.t)) hlE.add(e.id);
155	  }
156	
157	  const traced = traceEdges();
158	  traced.forEach(e => { hlE.add(e.id); hlN.add(e.f); hlN.add(e.t); });
159	
160	  svg.classList.toggle("has-focus", dim);
161	  for (const n of NODES) {
162	    const g = nodeG[n.id];
163	    g.classList.toggle("focus", n.id === f);
164	    g.classList.toggle("hl", dim && hlN.has(n.id) && n.id !== f);
165	    g.classList.toggle("dim", dim && !hlN.has(n.id));
166	  }
167	  for (const e of EDGES2) {
168	    const g = edgeG[e.id];
169	    g.classList.toggle("trace", traced.some(t => t.id === e.id));
170	    g.classList.toggle("hl", dim && hlE.has(e.id) && !traced.some(t => t.id === e.id));
171	    g.classList.toggle("dim", dim && !hlE.has(e.id));
172	    g.classList.toggle("peek", S.peek === e.id);
173	    const onTrace = traced.some(t => t.id === e.id);
174	    g.querySelector(".edge-line").setAttribute("marker-end", onTrace ? "url(#arr-trace)" : `url(#arr-${e.type})`);
175	  }
176	  if (f) {
177	    focusRing.setAttribute("x", byId[f].x - 6); focusRing.setAttribute("y", byId[f].y - 6);
178	    focusRing.setAttribute("visibility", "visible");
179	  } else focusRing.setAttribute("visibility", "hidden");
180	
181	  renderTracebar(f);
182	  renderPanel(f);
183	  renderTopstats(f);
184	  syncHash();
185	}
186	
187	/* ── 面包屑跟随条 ──────────────────────────────────────── */
188	const tracebar = document.getElementById("tracebar");
189	function renderTracebar(f) {
190	  const sig = S.path.join(",");
191	  if (sig === traceSig) return;
192	  traceSig = sig;
193	  tracebar.innerHTML = "";
194	  tracebar.hidden = S.path.length === 0;
195	  if (!S.path.length) return;
196	  S.path.forEach((id, i) => {
197	    if (i > 0) {
198	      const a = S.path[i - 1], b = id;
199	      const e = edgeById[`${a}~${b}`] || edgeById[`${b}~${a}`];
200	      const forward = e && e.f === a;
201	      const sep = document.createElement("span");
202	      sep.className = "crumb-sep";
203	      sep.style.color = e ? { call: "#3987e5", event: "#d95926", data: "#199e70" }[e.type] : "var(--ink-3)";
204	      sep.textContent = forward ? "─▸" : "◂─";
205	      sep.title = e ? `${e.f} 依赖 ${e.t}（${TYPE_NAME[e.type]}）` : "";
206	      tracebar.appendChild(sep);
207	    }
208	    const btn = document.createElement("button");
209	    btn.className = "crumb" + (id === f ? " cur" : "");
210	    btn.textContent = byId[id].name;
211	    btn.title = id === f ? "当前聚焦" : "回到这一步（保留前缀）";
212	    btn.addEventListener("click", () => { S.path = S.path.slice(0, i + 1); S.selEdge = null; render(); });
213	    tracebar.appendChild(btn);
214	  });
215	  const meta = document.createElement("span");
216	  meta.className = "crumb-meta";
217	  meta.textContent = `影响闭包 ${closureIn(f).size} · 依赖闭包 ${closureOut(f).size}`;
218	  tracebar.appendChild(meta);
219	  const clear = document.createElement("button");
220	  clear.className = "btn"; clear.textContent = "重置";
221	  clear.addEventListener("click", resetAll);
222	  tracebar.appendChild(clear);
223	}
224	
225	/* ── 右侧上下文面板 ────────────────────────────────────── */
226	const panel = document.getElementById("panel-body");
227	let panelSig = null, traceSig = null;   // 脏检查：悬停触发的重渲染不重建 DOM，避免 hover 抖动
228	const critChip = c => `<span class="crit ${c.toLowerCase()}">${c}</span>`;
229	const typeBadge = t => `<span class="tbadge ${t}">${TYPE_NAME[t]}</span>`;
230	
231	function relRow(e, otherId) {
232	  return `<button class="rel" data-nid="${otherId}" data-eid="${e.id}">
233	    ${typeBadge(e.type)}<span class="rel-name">${byId[otherId].name}</span>${critChip(e.crit)}
234	    <span class="rel-label">${e.label}</span></button>`;
235	}
236	
237	function renderPanel(f) {
238	  const sig = S.selEdge ? `e:${S.selEdge}` : f ? `n:${f}` : "ov";
239	  if (sig === panelSig) return;
240	  panelSig = sig;
241	  if (S.selEdge) return renderEdgeCard(edgeById[S.selEdge]);
242	  if (f) return renderNodeCard(byId[f]);
243	  renderOverview();
244	}
245	
246	function renderOverview() {
247	  const deg = id => inEdges[id].length + outEdges[id].length;
248	  const hubs = NODES.map(n => n.id).sort((a, b) => deg(b) - deg(a)).slice(0, 5);
249	  const p0 = EDGES2.filter(e => e.crit === "P0").length;
250	  const laneRows = LANES.map(l => {
251	    const cnt = NODES.filter(n => n.lane === l.id).length;
252	    const w = Math.round(cnt / 9 * 100);
253	    return `<div class="row"><span style="width:104px;flex:none">${l.name}</span>
254	      <span class="bar" style="--lc:${l.accent};width:${w}%"></span><span class="n">${cnt}</span></div>`;
255	  }).join("");
256	  const keyIds = ["order~inventory", "order~pay", "pay~wxpay", "pay~alipay", "order~mq"];
257	  const keyEdges = keyIds.map(id => {
258	    const e = edgeById[id];
259	    return `<button class="rel" data-eid="${e.id}" data-nid="">
260	      ${typeBadge(e.type)}<span class="rel-name">${byId[e.f].name} ▸ ${byId[e.t].name}</span>${critChip(e.crit)}</button>`;
261	  }).join("");
262	  panel.innerHTML = `
263	    <div class="pcard-sec">
264	      <div class="pkick">全局概览</div>
265	      <h2>${META.title}</h2>
266	      <p class="pdesc">${META.note}</p>
267	    </div>
268	    <div class="statrow grid3">
269	      <div><b>${NODES.length}</b><span>节点</span></div>
270	      <div><b>${EDGES2.length}</b><span>关系</span></div>
271	      <div><b>${p0}</b><span>P0 关系</span></div>
272	    </div>
273	    <h3>分层构成 <small>6 层</small></h3>
274	    <div class="lane-summary">${laneRows}</div>
275	    <h3>枢纽节点 <small>按连接度</small></h3>
276	    <div class="rel-list">${hubs.map(id =>
277	      `<button class="rel" data-nid="${id}" data-eid=""><span class="rel-name">${byId[id].name}</span>
278	       <span class="rel-label">${deg(id)} 连接</span></button>`).join("")}</div>
279	    <h3>P0 关键链路 <small>点击查看关系</small></h3>
280	    <div class="rel-list">${keyEdges}</div>
281	    <h3>怎么用</h3>
282	    <p class="pnote">点击任意节点开始「跟随」：相邻节点可继续行走，路径会累计成面包屑；整张关系网始终可见——其余节点只降暗，<b style="color:var(--ink-2)">不隐藏、不替换</b>，全局上下文永不丢失。</p>`;
283	}
284	
285	function renderNodeCard(n) {
286	  const outs = outEdges[n.id].slice().sort((a, b) => CRIT_ORDER[a.crit] - CRIT_ORDER[b.crit]);
287	  const ins = inEdges[n.id].slice().sort((a, b) => CRIT_ORDER[a.crit] - CRIT_ORDER[b.crit]);
288	  panel.innerHTML = `
289	    <div class="pcard-sec">
290	      <div class="pkick">节点 · ${laneById[n.lane].name}${n.lane === "ext" ? "（外部）" : ""}</div>
291	      <h2>${n.name}</h2>
292	      <p class="pdesc">${n.desc}</p>
293	      <div class="chips"><span class="chip">团队 · ${n.team}</span></div>
294	    </div>
295	    <div class="statrow">
296	      <div><b>${outs.length}</b><span>直接依赖</span></div>
297	      <div><b>${ins.length}</b><span>直接被依赖</span></div>
298	      <div><b>${closureOut(n.id).size}</b><span>依赖闭包</span></div>
299	      <div><b>${closureIn(n.id).size}</b><span>影响闭包</span></div>
300	    </div>
301	    <h3>它依赖 <small>出边 ${outs.length}</small></h3>
302	    <div class="rel-list">${outs.length ? outs.map(e => relRow(e, e.t)).join("") : '<div class="empty-list">无 —— 它不依赖任何节点</div>'}</div>
303	    <h3>被谁依赖 <small>入边 ${ins.length} · 出故障时受影响</small></h3>
304	    <div class="rel-list">${ins.length ? ins.map(e => relRow(e, e.f)).join("") : '<div class="empty-list">无 —— 没有节点依赖它</div>'}</div>
305	    <div class="btnrow">
306	      <button class="btn" id="btn-mode-deps">看它依赖什么（闭包 ${closureOut(n.id).size}）</button>
307	      <button class="btn" id="btn-mode-impact">看谁受它影响（闭包 ${closureIn(n.id).size}）</button>
308	    </div>`;
309	  document.getElementById("btn-mode-deps").addEventListener("click", () => setMode("deps"));
310	  document.getElementById("btn-mode-impact").addEventListener("click", () => setMode("impact"));
311	}
312	
313	function renderEdgeCard(e) {
314	  const a = byId[e.f], b = byId[e.t];
315	  panel.innerHTML = `
316	    <div class="pcard-sec">
317	      <div class="pkick">关系 · ${TYPE_NAME[e.type]}（${e.proto}）${b.lane === "ext" ? " · 跨边界" : ""}</div>
318	      <div class="edgerel">
319	        <button data-nid="${a.id}" data-eid="">${a.name}</button>
320	        <span class="edge-arrow ${e.type}" title="${a.name} 依赖 ${b.name}">──${TYPE_GLYPH[e.type]}</span>
321	        <button data-nid="${b.id}" data-eid="">${b.name}</button>
322	      </div>
323	      <p class="pdesc">${e.label} —— ${e.desc}</p>
324	    </div>
325	    <div class="chips">
326	      <span class="chip">类型 · ${TYPE_NAME[e.type]}</span>
327	      <span class="chip">协议 · ${e.proto}</span>
328	      <span class="chip">${critChip(e.crit)} 关键性</span>
329	    </div>
330	    <div class="statrow grid3" style="margin-top:14px">
331	      <div><b>${outEdges[a.id].length}</b><span>${a.name} 的依赖</span></div>
332	      <div><b>${inEdges[b.id].length}</b><span>${b.name} 被依赖</span></div>
333	      <div><b>${closureIn(b.id).size}</b><span>${b.name} 影响闭包</span></div>
334	    </div>
335	    <h3>继续跟随</h3>
336	    <div class="rel-list">
337	      <button class="rel" data-nid="${a.id}" data-eid=""><span class="rel-name">▸ ${a.name}</span><span class="rel-label">上游（依赖方）</span></button>
338	      <button class="rel" data-nid="${b.id}" data-eid=""><span class="rel-name">▸ ${b.name}</span><span class="rel-label">下游（被依赖方）</span></button>
339	    </div>
340	    <p class="pnote" style="margin-top:12px">关系即内容：${TYPE_NAME[e.type]}${e.type === "event" ? "意味着解耦——故障传播慢一拍但同样到达" : e.type === "data" ? "意味着数据契约——模式变更需双向协同" : "意味着同步依赖——可用性直接受下游牵连"}。</p>`;
341	}
342	
343	/* ── 顶栏统计 ──────────────────────────────────────────── */
344	const topstats = document.getElementById("topstats");
345	function renderTopstats(f) {
346	  topstats.innerHTML = f
347	    ? `聚焦 <b>${byId[f].name}</b> · ${NODES.length} 节点 · ${EDGES2.length} 关系`
348	    : `<b>${NODES.length}</b> 节点 · <b>${EDGES2.length}</b> 关系 · <b>${LANES.length}</b> 层`;
349	}
350	
351	/* ── 交互：跟随 ────────────────────────────────────────── */
352	function followTo(id) {
353	  if (!byId[id]) return;
354	  S.selEdge = null;
355	  const cur = S.path[S.path.length - 1];
356	  if (cur && cur !== id && neighbors[cur].has(id)) S.path.push(id);   // 相邻：累计跟随
357	  else if (cur !== id) S.path = [id];                                  // 跳转：新起路径
358	  render();
359	}
360	function resetAll() { S.path = []; S.selEdge = null; setMode("adj"); }
361	function setMode(m) {
362	  S.mode = m;
363	  document.querySelectorAll(".modes button").forEach(b => b.classList.toggle("on", b.dataset.mode === m));
364	  render();
365	}
366	
367	/* 事件委托（面板内按钮） */
368	panel.addEventListener("click", ev => {
369	  const b = ev.target.closest("button"); if (!b) return;
370	  const nid = b.dataset.nid, eid = b.dataset.eid;
371	  if (nid) followTo(nid);
372	  else if (eid) { S.selEdge = eid; render(); }   // 保留跟随路径：查看关系不丢弃全局上下文
373	});
374	panel.addEventListener("mouseover", ev => {
375	  const b = ev.target.closest("button"); if (!b) return;
376	  S.peek = b.dataset.eid || null; render();
377	});
378	panel.addEventListener("mouseout", () => { if (S.peek) { S.peek = null; render(); } });
379	
380	document.querySelectorAll(".modes button").forEach(b => b.addEventListener("click", () => setMode(b.dataset.mode)));
381	document.getElementById("btn-reset").addEventListener("click", resetAll);
382	
383	/* SVG 上的点击（拖拽平移后的 click 需抑制） */
384	let panMoved = false;
385	svg.addEventListener("click", ev => {
386	  if (panMoved) { panMoved = false; return; }
387	  const ng = ev.target.closest(".node-g");
388	  const hit = ev.target.closest(".edge-hit");
389	  if (ng) { followTo(ng.dataset.nid); return; }
390	  if (hit) { S.selEdge = hit.parentNode.dataset.eid; render(); return; }
391	  if (S.selEdge) { S.selEdge = null; render(); }   // 点空白处 = 取消关系选中（跟随路径保留）
392	});
393	
394	/* ── 提示气泡 ──────────────────────────────────────────── */
395	const tooltip = document.getElementById("tooltip");
396	function showTip(ev, html) {
397	  tooltip.innerHTML = html; tooltip.hidden = false;
398	  const r = stage.getBoundingClientRect();
399	  let x = ev.clientX - r.left + 14, y = ev.clientY - r.top + 14;
400	  x = Math.min(x, r.width - tooltip.offsetWidth - 8);
401	  y = Math.min(y, r.height - tooltip.offsetHeight - 8);
402	  tooltip.style.left = x + "px"; tooltip.style.top = y + "px";
403	}
404	svg.addEventListener("mousemove", ev => {
405	  const ng = ev.target.closest(".node-g");
406	  const hit = ev.target.closest(".edge-hit");
407	  if (ng) {
408	    const n = byId[ng.dataset.nid];
409	    showTip(ev, `<b>${n.name}</b><div class="tt-sub">${laneById[n.lane].name} · ${n.team}</div><div class="tt-sub">${n.desc}</div>`);
410	  } else if (hit) {
411	    const e = edgeById[hit.parentNode.dataset.eid];
412	    showTip(ev, `<b>${byId[e.f].name} ${TYPE_GLYPH[e.type]} ${byId[e.t].name}</b>
413	      <div class="tt-sub">${e.label} · ${TYPE_NAME[e.type]} · ${e.proto} · ${e.crit}</div>`);
414	  } else tooltip.hidden = true;
415	});
416	svg.addEventListener("mouseleave", () => { tooltip.hidden = true; });
417	svg.addEventListener("mouseover", ev => {
418	  const hit = ev.target.closest(".edge-hit");
419	  S.peek = hit ? hit.parentNode.dataset.eid : null; render();
420	});
421	
422	/* ── 搜索 ──────────────────────────────────────────────── */
423	const searchInput = document.getElementById("search");
424	const searchDrop = document.getElementById("search-drop");
425	function doSearch(q) {
426	  q = q.trim().toLowerCase();
427	  if (!q) { searchDrop.hidden = true; return; }
428	  const hits = NODES.filter(n => n.name.toLowerCase().includes(q) || n.id.includes(q) || n.desc.includes(q)).slice(0, 8);
429	  if (!hits.length) { searchDrop.hidden = true; return; }
430	  searchDrop.innerHTML = hits.map(n =>
431	    `<button data-nid="${n.id}"><span>${n.name}</span><span class="s-lane">${laneById[n.lane].name}</span></button>`).join("");
432	  searchDrop.hidden = false;
433	}
434	searchInput.addEventListener("input", () => doSearch(searchInput.value));
435	searchInput.addEventListener("keydown", ev => {
436	  if (ev.key === "Enter") {
437	    const first = searchDrop.querySelector("button");
438	    if (first) { followTo(first.dataset.nid); searchDrop.hidden = true; searchInput.value = ""; searchInput.blur(); }
439	  } else if (ev.key === "Escape") { searchDrop.hidden = true; searchInput.blur(); }
440	});
441	searchDrop.addEventListener("click", ev => {
442	  const b = ev.target.closest("button"); if (!b) return;
443	  followTo(b.dataset.nid);
444	  searchDrop.hidden = true; searchInput.value = "";
445	});
446	
447	/* ── 平移与缩放（viewBox） ─────────────────────────────── */
448	const VB = { x: 0, y: 0, w: CW, h: CH };
449	function applyVB() { svg.setAttribute("viewBox", `${VB.x} ${VB.y} ${VB.w} ${VB.h}`); }
450	function fitView() {
451	  const r = stage.getBoundingClientRect();
452	  const ar = r.width / Math.max(r.height, 1), dar = CW / CH;
453	  if (ar > dar) { VB.h = CH; VB.w = CH * ar; VB.x = (CW - VB.w) / 2; VB.y = 0; }
454	  else { VB.w = CW; VB.h = CW / ar; VB.x = 0; VB.y = (CH - VB.h) / 2; }
455	  applyVB();
456	}
457	function svgPoint(cx, cy) {
458	  const p = svg.createSVGPoint(); p.x = cx; p.y = cy;
459	  return p.matrixTransform(svg.getScreenCTM().inverse());
460	}
461	function zoomAt(cx, cy, f) {
462	  const w = Math.min(Math.max(VB.w * f, 320), CW * 3.2);
463	  f = w / VB.w;
464	  const pt = svgPoint(cx, cy);
465	  VB.x = pt.x - (pt.x - VB.x) * f; VB.y = pt.y - (pt.y - VB.y) * f;
466	  VB.w *= f; VB.h *= f; applyVB();
467	}
468	stage.addEventListener("wheel", ev => { ev.preventDefault(); zoomAt(ev.clientX, ev.clientY, ev.deltaY > 0 ? 1.12 : 1 / 1.12); }, { passive: false });
469	function zoomCenter(f) {
470	  const r = stage.getBoundingClientRect();
471	  zoomAt(r.left + r.width / 2, r.top + r.height / 2, f);
472	}
473	document.getElementById("btn-zin").addEventListener("click", () => zoomCenter(1 / 1.25));
474	document.getElementById("btn-zout").addEventListener("click", () => zoomCenter(1.25));
475	
476	let pan = null;
477	svg.addEventListener("pointerdown", ev => {
478	  if (ev.target.closest(".node-g") || ev.target.closest(".edge-hit")) return;
479	  pan = { x: ev.clientX, y: ev.clientY, vx: VB.x, vy: VB.y };
480	  svg.classList.add("panning"); svg.setPointerCapture(ev.pointerId);
481	});
482	svg.addEventListener("pointermove", ev => {
483	  if (!pan) return;
484	  if (Math.abs(ev.clientX - pan.x) + Math.abs(ev.clientY - pan.y) > 3) panMoved = true;
485	  const r = stage.getBoundingClientRect();
486	  VB.x = pan.vx - (ev.clientX - pan.x) * VB.w / r.width;
487	  VB.y = pan.vy - (ev.clientY - pan.y) * VB.h / r.height;
488	  applyVB();
489	});
490	svg.addEventListener("pointerup", () => { pan = null; svg.classList.remove("panning"); });
491	document.getElementById("btn-fit").addEventListener("click", fitView);
492	window.addEventListener("resize", fitView);
493	
494	/* ── 键盘 ──────────────────────────────────────────────── */
495	window.addEventListener("keydown", ev => {
496	  if (ev.target.tagName === "INPUT") return;
497	  if (ev.key === "Escape") resetAll();
498	  if (ev.key === "f" || ev.key === "F") fitView();
499	});
500	
501	/* ── 深链（#p=a>b>c&m=impact / #e=a~b）────── 同一交互代码路径 */
502	function syncHash() {
503	  let h = "";
504	  if (S.selEdge) h = `e=${S.selEdge}`;
505	  else if (S.path.length) h = `p=${S.path.join(">")}&m=${S.mode}`;
506	  try { history.replaceState(null, "", h ? "#" + h : location.pathname); } catch (_) { /* file:// 下可能受限 */ }
507	}
508	function parseHash() {
509	  const h = location.hash.slice(1);
510	  if (!h) return;
511	  const q = new URLSearchParams(h);
512	  const e = q.get("e");
513	  if (e && edgeById[e]) { S.selEdge = e; return; }
514	  const p = q.get("p");
515	  if (p) {
516	    const ids = p.split(">").map(s => s.trim()).filter(id => byId[id]);
517	    // 只保留可达的连续路径片段
518	    const ok = [];
519	    for (const id of ids) {
520	      const cur = ok[ok.length - 1];
521	      if (!cur || neighbors[cur].has(id) || id === cur) ok.push(id); else break;
522	    }
523	    if (ok.length) S.path = ok;
524	  }
525	  const m = q.get("m");
526	  if (["adj", "deps", "impact"].includes(m)) { S.mode = m; document.querySelectorAll(".modes button").forEach(b => b.classList.toggle("on", b.dataset.mode === m)); }
527	}
528	
529	/* ── 启动：同步构建 + 首屏即渲染，无加载态 ─────────────── */
530	buildDefs(); buildLanes(); buildEdges(); buildNodes();
531	parseHash();
532	fitView();
533	render();
534

